// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, optionFigures, steps, context, audio, numericAnswer} = row;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(figure || optionFigures ? {choiceLayout: {condition: figure, options},
        choiceImages: options.map(option => option.image),
        ...(figure ? {conditionImage: figure.src, conditionAlt: figure.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"british-bulldog","year":2020,"grade":"9-11","contest":"British Bulldog","letters":"ABCD","count":60,"language":"en","points":3,"tasksFile":"9-11/tasks.pdf","answersFile":"reviewed-9-11.pdf","listeningFile":"9-11/listening.mp3","sections":[{"start":1,"title":"Listening"},{"start":11,"title":"Reading"},{"start":21,"title":"Grammar"},{"start":31,"title":"Sports"},{"start":41,"title":"The office"},{"start":51,"title":"Literary characters"}],"titleLanguage":"en","reviewedKey":true}, [{"title":"Anna Morrison’s Age","question":"How old is Anna Morrison?","context":"Listen to the dialogue and answer the questions","choices":["15","16","30","They didn’t say"],"answer":1,"steps":["Ведущий представляет Анну в начале. Её возраст звучит непосредственно перед словом inventor.","Он говорит «sixteen-year-old inventor». Анне 16 лет."],"audio":true},{"title":"What Anna Did","question":"What did she do? She ... something for students.","context":"Listen to the dialogue and answer the questions","choices":["drew","invented","investigated","researched"],"answer":1,"steps":["Ведущий говорит о полезной вещи для учеников. Слушай глагол в предложении «Anna, you’ve … something useful for students».","Он говорит «you’ve invented». Invented значит «изобрела»."],"audio":true},{"title":"Naming the Box","question":"What did she call it? ... Box.","context":"Listen to the dialogue and answer the questions","choices":["Chatter","Memory","Imagination","Helpful"],"answer":1,"steps":["Анна начинает объяснение с «It’s an invention called …». Дальше она называет программу.","Название — Memory Box, буквально «коробка памяти»."],"audio":true},{"title":"What the Invention Is For","question":"What is the aim of this invention? To help students ... .","context":"Listen to the dialogue and answer the questions","choices":["relax","make experiments","learn things","revise the material"],"answer":2,"steps":["Анна говорит, что программа «helps you remember things». В неё вводят материал, который ещё нужно выучить.","Из вариантов лучше всего подходит learn things — «учиться и запоминать новое». Программу также можно использовать для повторения."],"audio":true},{"title":"How Anna Got the Idea","question":"What gave rise to its creation? Anna ... to learn Spanish words.","context":"Listen to the dialogue and answer the questions","choices":["needed","failed","was glad","was happy"],"answer":0,"steps":["Анна объясняет, что преподаватель испанского дал ей список тридцати новых слов. Слушай, какую задачу ей поставили.","Слова нужно было выучить. Needed to learn передаёт эту необходимость."],"audio":true},{"title":"The Kind of Invention","question":"What is her invention like? It’s a ... .","context":"Listen to the dialogue and answer the questions","choices":["film","computer programme","video","presentation"],"answer":1,"steps":["Различи само изобретение и видео с инструкцией. Анна рассказывает, что воспользовалась умением писать программы.","Memory Box — компьютерная программа на сайте. Подходит computer programme."],"audio":true},{"title":"How the Invention Works","question":"How does the invention work? It ... .","context":"Listen to the dialogue and answer the questions","choices":["shows pictures","plays background music","shows films","repeats information in different ways"],"answer":3,"steps":["Анна говорит, что программа делает игры на основе введённых данных. Слушай объяснение после «again and again».","Выражение «but differently each time» означает «каждый раз по-разному». Программа repeats information in different ways."],"audio":true},{"title":"Anna’s First Reaction","question":"How did Anna feel at first after having created the Box?","context":"Listen to the dialogue and answer the questions","choices":["Nervous","Proud","Tired","Indifferent"],"answer":1,"steps":["Ведущий спрашивает о моменте, когда Анна представила программу публике. Она говорит, что создала то, чем могла гордиться.","В записи звучит «something I could be proud of». Proud — «гордая»."],"audio":true},{"title":"Improving the Invention","question":"What did Anna do to improve her invention? She ... .","context":"Listen to the dialogue and answer the questions","choices":["made a video demonstration","changed the computer programme","rewrote the instructions","deleted the instructions"],"answer":0,"steps":["Люди не понимали, как переходить между этапами. Анна рассказывает, что первоначальное видео объясняло это плохо.","Она перезаписала демонстрационное видео с помощью друга. Из вариантов подходит made a video demonstration."],"audio":true},{"title":"What Teachers Contribute","question":"What do many teachers do for other people to learn on this site?","context":"Listen to the dialogue and answer the questions","choices":["Add facts","Make presentations","Create games","Write instructions"],"answer":0,"steps":["Слушай заключительный ответ Анны. Она говорит, что любой может добавить «your own list of facts».","Многие учителя добавляют в программу списки фактов для других. Подходит Add facts."],"audio":true},{"title":"Who Fell in Love?","question":"Who fell in love with a young girl?","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["A Professor","The girl’s father","A student","Nobody"],"answer":2,"steps":["Первое предложение называет того, кто «was in love with the daughter of a Professor».","Автор говорит о молодом студенте — A student."]},{"title":"The Upcoming Event","question":"What event was going to take place?","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["A duel","A ball","A dating","A meeting"],"answer":1,"steps":["Девушка обещает потанцевать со студентом при определённом условии. Найди слова «at the Prince’s …».","Она говорит о бале принца. A ball здесь означает «бал»."]},{"title":"A Condition for Dancing","question":"On what condition would the girl dance with her admirer? If he gave her a ... .","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["thorn","ring","promise","red flower"],"answer":3,"steps":["В начале сказки после if указано, что студент должен принести девушке. Ищи слова red roses.","Роза — цветок. Из вариантов подходит red flower — «красный цветок»."]},{"title":"Someone Comes to Help","question":"Who decided to help the admirer?","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["A bird","Nobody","A Professor","The girl’s father"],"answer":0,"steps":["Студента услышал nightingale. Следующее предложение говорит, что это существо решило помочь.","Nightingale — соловей, то есть птица. Ответ A bird."]},{"title":"Why the Helper Cared","question":"Why did the well-wisher want to help? Because ... .","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["it was her duty","it was true love","she had to do it","it would please the girl"],"answer":1,"steps":["Соловей услышал плач студента. Автор пишет, что птица считала его «a true lover».","По мнению птицы, студент любил по-настоящему. Это соответствует it was true love."]},{"title":"A Discovery the Next Day","question":"What did the student find the next day?","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["A red rose","Nothing happened","A white rose","Nothing changed"],"answer":0,"steps":["Найди предложение, начинающееся с «The next day». Дальше сказано, что увидел студент.","«The student found the red rose» означает, что он нашёл красную розу."]},{"title":"The Cost of the Rose","question":"What was the price for a red rose?","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["It cost nothing","The well-wisher’s life","100 pounds","The girl’s smile"],"answer":1,"steps":["Price здесь означает не только денежную цену. В сказке за появление красной розы пришлось чем-то пожертвовать.","Соловей погиб, чтобы роза появилась. Ответ The well-wisher’s life — «жизнь того, кто хотел помочь»."]},{"title":"Which Gift She Preferred","question":"Which present did the girl appreciate more?","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["The red rose","Jewels","A new dress","A book"],"answer":1,"steps":["В конце девушка сравнивает цветок с другим подарком. Автор использует «was more impressed by …».","Её больше впечатлили украшения — Jewels."]},{"title":"The Girl and the Flower","question":"How did the girl react to the flower?","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["She put it into a vase","She was more impressed by the jewels","She gave the flower to her father","She pinned it to her dress"],"answer":1,"steps":["После того как студент приносит цветок, рассказчик описывает реакцию девушки. Найди фразу о том, что произвело на неё большее впечатление.","В рассказе написано «the girl … was more impressed by jewels than by the poor student’s flower». Подходит B."],"reviewedEdition":true},{"title":"What the Student Did Next","question":"What did the student do? He ... .","context":"Read the story and answer the questions\n\nThere was once a young student who was in love with the daughter of a Professor. The girl told the student that she would only dance with him at the Prince’s ball if he brought her red roses. Unfortunately, the student had no roses in his garden. While he was crying, a nightingale heard him and felt sorry for him because she believed that he was a true lover. She decided to help him, and flew to a rose tree, but the rose tree had only white roses. Another rose tree had only yellow roses. At last she found the rose tree which grew red roses, but this year it didn’t have any roses. The nightingale begged the rose tree to tell her how to get a red rose. Reluctantly the tree explained that she would have to kill herself by pressing against a thorn while singing. After a moment’s thought the nightingale decided to do this. At night the nightingale sang the songs pressing against a thorn until she died. The next day the student found the red rose and rushed to the Professor’s house. The girl, however, was more impressed by jewels than by the poor student’s flower, besides the latter didn’t match her dress. Disillusioned, the student went home and returned to his books.","choices":["was in despair","burst into tears","continued studying","fell ill"],"answer":2,"steps":["Читай самое последнее предложение. После разочарования студент идёт домой.","«Returned to his books» означает, что он снова взялся за книги. Подходит continued studying."]},{"title":"Hungry After Lunch","question":"You ... be hungry again! You had a big lunch an hour ago.","context":"Fill in the blanks with the correct option","choices":["mustn’t","can’t","don’t have to","aren’t"],"answer":1,"steps":["Говорящий считает голод невероятным из-за недавнего обильного обеда. Это вывод о ситуации, а не запрет.","Can’t be выражает уверенность, что что-то невозможно: «You can’t be hungry again!»"]},{"title":"Knowing Paul","question":"How long ... Paul?","context":"Fill in the blanks with the correct option","choices":["have you known","do you know","are you knowing","you know"],"answer":0,"steps":["How long спрашивает, сколько времени продолжается знакомство. Оно началось в прошлом и длится сейчас.","Нужен Present Perfect: have + known. В вопросе have стоит перед you."]},{"title":"Bringing Dictionaries","question":"Please ... your English dictionaries tomorrow.","context":"Fill in the blanks with the correct option","choices":["remind to bring","remember to bring","remember bringing","didn’t forget bringing"],"answer":1,"steps":["Tomorrow сообщает, что словари ещё предстоит принести. Нужно попросить человека не забыть это сделать.","Такое значение выражает remember to bring. Remember bringing относится к воспоминанию об уже совершённом действии."]},{"title":"Accusing a Classmate","question":"He accused her ... his homework.","context":"Fill in the blanks with the correct option","choices":["to copy","copying","that she has copied","of copying"],"answer":3,"steps":["Accused значит «обвинил». После her нужно указать, в чём он её обвиняет.","Говорим accuse someone of doing something. Получается accused her of copying."]},{"title":"A Test the Following Week","question":"The teacher said that they ... a test the following week.","context":"Fill in the blanks with the correct option","choices":["would have","have been having","will had","are going have"],"answer":0,"steps":["Учитель сообщал о будущем из точки в прошлом. Said и the following week указывают на косвенную речь.","Will в такой конструкции обычно меняется на would. Получаем «they would have a test»."]},{"title":"A Secret Told to Jim","question":"He denied ... Jim her secret.","context":"Fill in the blanks with the correct option","choices":["he was told","that he said","to tell","telling"],"answer":3,"steps":["Denied означает «отрицал». В пропуске нужно назвать действие, которое человек отрицает.","После deny употребляется форма на -ing: «denied telling Jim her secret»."]},{"title":"Late Without an Apology","question":"... she was late, she didn’t apologise.","context":"Fill in the blanks with the correct option","choices":["In spite of","Although","However","Even"],"answer":1,"steps":["Между двумя сообщениями есть уступка: она опоздала и всё же не извинилась. После пропуска дано придаточное she was late.","Although = «хотя» и вводит это придаточное. После in spite of понадобилась бы именная группа или оборот the fact that."]},{"title":"Comparing Musicians","question":"He isn’t a good guitarist but he sings ... the others in the group.","context":"Fill in the blanks with the correct option","choices":["very better than","much better than","as well","more better than"],"answer":1,"steps":["He sings сравнивается с тем, как поют остальные. Нужна сравнительная форма от well и слово than.","У well сравнительная форма better. Усилитель much сочетается с ней: much better than."]},{"title":"Standing in Long Queues","question":"I can’t stand … in long queues!","context":"Fill in the blanks with the correct option","choices":["waits","waiting","I am waiting","that I waiting"],"answer":1,"steps":["Can’t stand означает «терпеть не могу». После него можно поставить форму на -ing, чтобы назвать неприятное занятие.","Выбираем waiting. Получается «I can’t stand waiting in long queues» — «Терпеть не могу стоять в длинных очередях»."],"reviewedEdition":true},{"title":"The Boy by the Window","question":"Tom is the tall, ... boy standing by the window.","context":"Fill in the blanks with the correct option","choices":["eyes blue","blue-eyed","blue-eyes","eyed-blue"],"answer":1,"steps":["Перед boy нужно сложное прилагательное со значением «голубоглазый».","Сначала ставим цвет, затем -eyed: blue-eyed. Выбираем B."]},{"title":"A Sport from Japan","question":"It’s Japan’s national sport in which the athletes are mostly very fat.","context":"Choose the right word for the sport","choices":["Boxing","Sumo","Fencing","Swimming"],"answer":1,"steps":["Основная подсказка — традиционный японский вид борьбы. В нём борцы стараются вытеснить соперника из круга или заставить его коснуться земли.","Речь о сумо — Sumo."]},{"title":"Equipment for the Sport","question":"To do this sport you need special breathing equipment and flippers.","context":"Choose the right word for the sport","choices":["Swimming","Ski jumping","Water polo","Scuba diving"],"answer":3,"steps":["Flippers — ласты. Специальное оборудование для дыхания позволяет находиться под водой дольше, чем при обычном плавании.","Из вариантов подходит погружение с аквалангом — Scuba diving."]},{"title":"Racing Over Fences","question":"The animals and their riders take part in races over hurdles or fences.","context":"Choose the right word for the sport","choices":["Fencing","Curling","Rafting","Horse racing"],"answer":3,"steps":["Riders — всадники, hurdles и fences — препятствия, через которые нужно перепрыгнуть.","Описание относится к скачкам с препятствиями. Из вариантов подходит Horse racing."]},{"title":"Carabiners and Rope","question":"It’s good if you aren’t afraid of heights and have carabiners and a rope.","context":"Choose the right word for the sport","choices":["Diving","Fencing","Triathlon","Rock climbing"],"answer":3,"steps":["Heights — высота. Карабины и верёвка используются для страховки при подъёме.","Из вариантов такому занятию соответствует скалолазание — Rock climbing."]},{"title":"Racing Down a River","question":"The participants race down dangerous whitewater rivers.","context":"Choose the right word for the sport","choices":["Fencing","Curling","Kayaking","Ski jumping"],"answer":2,"steps":["Whitewater — бурная вода с порогами. Нужен вид спорта, в котором участники спускаются по такой реке на лодке.","Из данных вариантов подходит Kayaking, прохождение реки на каяке."]},{"title":"Track and Field Events","question":"Hurdles, discus, pole vault and long jump are events in ... .","context":"Choose the right word for the sport","choices":["athletics","acrobatics","gymnastics","surfing"],"answer":0,"steps":["В перечне бег с барьерами, метание диска, прыжок с шестом и прыжок в длину.","Все эти дисциплины входят в лёгкую атлетику, которая по-британски называется athletics."]},{"title":"A Ball, Rope and Ribbon","question":"The participants use a ball, rope, ribbon and hoop in this sport.","context":"Choose the right word for the sport","choices":["Boxing","Rhythmic gymnastics","Athletics","Figure skating"],"answer":1,"steps":["Ball, rope, ribbon и hoop — мяч, скакалка, лента и обруч. Такое оборудование используется для упражнений под музыку.","Это художественная гимнастика — Rhythmic gymnastics."]},{"title":"A Game on Horseback","question":"To do this sport you should ride horses.","context":"Choose the right word for the sport","choices":["Polo","Cricket","Bandy","Rugby"],"answer":0,"steps":["Из вариантов нужно выбрать игру, в которой участники ездят верхом. В этой игре всадники ударяют по мячу длинными клюшками.","Это конное поло — Polo."]},{"title":"Playing with Brooms","question":"You need special brooms to play this game.","context":"Choose the right word for the sport","choices":["Polo","Curling","Bandy","Cricket"],"answer":1,"steps":["Специальные щётки нужны на льду. Игроки обрабатывают поверхность перед скользящим камнем.","Так играют в кёрлинг — Curling."]},{"title":"A Large Playing Area","question":"To play this game it is necessary to have a very large “field”, which is called a course.","context":"Choose the right word for the sport","choices":["Football","Golf","Rugby","Cricket"],"answer":1,"steps":["Слово course здесь обозначает площадку, на которой расположено несколько лунок. Игроки переходят между ними.","Это golf course, поле для гольфа. Ответ Golf."]},{"title":"Identifying the Room","question":"In the picture we see a ... .","context":"Choose the correct variants to describe the office","choices":["lounge","kitchen","study","dining room"],"answer":2,"steps":["На рисунке есть письменный стол с компьютером, офисное кресло и шкаф для документов.","Из предложенных комнат подходит study — «кабинет»."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"Documents on the Wall","question":"You can see many ... on the wall.","context":"Choose the correct variants to describe the office","choices":["photos","pictures","reports","certificates"],"answer":3,"steps":["Слева от часов на стене висят листы с печатями, рамками и значками. Они похожи на документы о достижениях.","Такие документы называют certificates — «сертификаты» или «грамоты»."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"To the Right of the Table","question":"To the right of the table there is ... .","context":"Choose the correct variants to describe the office","choices":["an armchair","an office chair","a globe","a filing cabinet"],"answer":3,"steps":["Найди стол с компьютером. Справа от него стоит высокий предмет с рядами папок.","Это шкаф для документов — a filing cabinet."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"Where the Folders Are","question":"There are many folders ... .","context":"Choose the correct variants to describe the office","choices":["on the shelf","in the filing cabinet","on the chair","under the table"],"answer":1,"steps":["Цветные папки стоят на полках высокого шкафа справа. На отдельной настенной полке слева видны другие предметы.","Ключ указывает на место более конкретно — in the filing cabinet, «в шкафу для документов»."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"What the Owner Likes","question":"The owner of the room is fond of these things because there are many of them in the office.","context":"Choose the correct variants to describe the office","choices":["plants","lamps","books","canvases"],"answer":0,"steps":["Ищи предметы, которые повторяются в нескольких местах. Горшки с зеленью видны на шкафу, на столе и на полу.","Из вариантов автор имеет в виду plants — растения."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"Something to Drink","question":"If you are thirsty you can ... .","context":"Choose the correct variants to describe the office","choices":["make tea","turn off the light","have a snack","smell the plants"],"answer":0,"steps":["Thirsty значит «хочется пить». Выбери действие, после которого можно выпить напиток.","Из предложенных действий подходит make tea — «заварить чай»."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"Inside the Dust Bin","question":"There is a lot of ... in the dust bin.","context":"Choose the correct variants to describe the office","choices":["luggage","cabbage","rubbish","baggage"],"answer":2,"steps":["Dust bin — мусорная корзина. Под столом на рисунке видно такую корзину с выброшенной бумагой.","Мусор — rubbish. Luggage и baggage означают «багаж», а cabbage — «капуста»."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"The Upper Left Corner","question":"You can see it in the upper left corner of the room.","context":"Choose the correct variants to describe the office","choices":["A glass","A globe","A statuette","A vase"],"answer":1,"steps":["Upper left corner означает «верхний левый угол». На полке там виден шар с очертаниями материков.","Это глобус — a globe."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"Next to the Filing Cabinet","question":"It is situated on the wall next to the filing cabinet.","context":"Choose the correct variants to describe the office","choices":["A map","A table","A calendar","A certificate"],"answer":2,"steps":["Найди шкаф с папками и посмотри сразу левее него. На стене висит лист с сеткой чисел.","Сеткой показаны дни месяца. Это календарь — A calendar."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"Light on the Desk","question":"It sits on a table top and is used to light up the room.","context":"Choose the correct variants to describe the office","choices":["A cup","A lamp","A monitor","A plant"],"answer":1,"steps":["Light up означает «освещать». Найди на столе предмет, который предназначен для этого.","На столе стоит настольная лампа — A lamp."],"figure":{"src":"assets/british-bulldog/2020/9-11/office.webp","alt":"An illustrated room with furniture and items on its walls.","width":648,"height":414}},{"title":"A Girl at Lowood School","question":"When a child she studied at Lowood School for orphans.","context":"Do you know the literary characters?","choices":["Dorothy","Alice","Jane Eyre","Scarlett O’Hara"],"answer":2,"steps":["Lowood — школа для девочек, в которой проходит часть детства героини романа Шарлотты Бронте.","Эту героиню зовут Jane Eyre — Джейн Эйр."]},{"title":"Who Is Missing from Lear?","question":"It is not the name of any of the daughters of King Lear.","context":"Do you know the literary characters?","choices":["Ophelia","Regan","Goneril","Cordelia"],"answer":0,"steps":["В трагедии «Король Лир» у героя три дочери — Гонерилья, Регана и Корделия.","Офелия — персонаж «Гамлета». Поэтому подходит Ophelia."]},{"title":"A Castaway’s Story","question":"After a shipwreck he found himself on a desert island, where he spent 28 years.","context":"Do you know the literary characters?","choices":["Tom Sawyer","Gulliver","Robinson Crusoe","Oliver Twist"],"answer":2,"steps":["Shipwreck — кораблекрушение. Речь о герое романа Даниэля Дефо, который прожил 28 лет на острове.","Это Робинзон Крузо — Robinson Crusoe."]},{"title":"Romeo and Juliet’s Town","question":"Romeo and Juliet lived in this Italian town.","context":"Do you know the literary characters?","choices":["Verona","Rome","Milan","Pompeii"],"answer":0,"steps":["Вспомни, в каком городе в трагедии Шекспира противостоят семьи Монтекки и Капулетти.","Оба героя живут в Вероне. Выбираем Verona."]},{"title":"A Boy with Magical Powers","question":"These books by J.K. Rowling about a boy with magical powers are popular all over the world.","context":"Do you know the literary characters?","choices":["Peter Pan","Tom Sawyer","Harry Potter","Gulliver"],"answer":2,"steps":["Вопрос о серии книг Джоан Роулинг. Её герой учится волшебству в школе Хогвартс.","Мальчика зовут Гарри Поттер. Серия носит его имя — Harry Potter."]},{"title":"A Man Who Hates Christmas","question":"This character created by Charles Dickens is a cold-hearted man who despises Christmas.","context":"Do you know the literary characters?","choices":["Oliver Twist","Nicholas Nickleby","David Copperfield","Ebenezer Scrooge"],"answer":3,"steps":["Despises Christmas — «презирает Рождество». Такой скупец — главный герой повести Диккенса A Christmas Carol.","Скупца зовут Эбенезер Скрудж. Ответ Ebenezer Scrooge."]},{"title":"The Magical Nanny","question":"She is perhaps the most famous magical English nanny.","context":"Do you know the literary characters?","choices":["Miss Marple","Mary Poppins","Mrs Hudson","Jane Eyre"],"answer":1,"steps":["Nanny — няня. Ищи героиню повестей Памелы Трэверс, с которой происходят волшебные события.","Это Мэри Поппинс — Mary Poppins."]},{"title":"A Knight Tournament","question":"He won at the Knight Tournament.","context":"Do you know the literary characters?","choices":["Huckleberry Finn","Tom Sawyer","Ivanhoe","Harry Potter"],"answer":2,"steps":["Речь о средневековом рыцарском турнире. Такой эпизод есть в историческом романе Вальтера Скотта.","На турнире в Эшби побеждает рыцарь Айвенго — Ivanhoe."]},{"title":"A Detective’s Biographer","question":"He was a famous detective’s friend and biographer.","context":"Do you know the literary characters?","choices":["John Watson","Huckleberry Finn","Hercule Poirot","Oliver Twist"],"answer":0,"steps":["Biographer — тот, кто описывает жизнь другого человека. Большинство рассказов о Шерлоке Холмсе написаны от лица его друга.","Друг и рассказчик — доктор Джон Ватсон. Ответ John Watson."]},{"title":"A Trip in a Balloon","question":"He flew in a balloon together with his friends.","context":"Do you know the literary characters?","choices":["Tom Sawyer","Peter Pan","Oliver Twist","Harry Potter"],"answer":0,"steps":["Важно, что герои летят на воздушном шаре. Следи за деталями путешествия, а не просто за тем, кто умеет летать.","В книге Tom Sawyer Abroad Том Сойер отправляется в путешествие на воздушном шаре вместе с Геком и Джимом."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
